outer = consecutive_groups([1, 2, 5], step=1)
print("types:", type(outer).__name__, type(next(outer)).__name__)

# --- Backward compatibility vs the original implementation
def original(iterable, ordering=None):
    if ordering is None:
        key = lambda x: x[0] - x[1]
    else:
        key = lambda x: x[0] - ordering(x[1])
    for k, g in groupby(enumerate(iterable), key=key):
        yield map(itemgetter(1), g)

def plain_generator_with_step(iterable, ordering=None, step=1):
    pos = ordering or (lambda x: x)
    for k, g in groupby(enumerate(iterable), key=lambda x: pos(x[1]) - step * x[0]):
        yield map(itemgetter(1), g)

def transcript(factory, data, ops):
    pulled, log, groups = [], [], []
    def source():
        for x in data:
            pulled.append(x)
            yield x
    outer = factory(source())
    log.append(('after call', len(pulled)))
    for op in ops:
        if op == 'outer' or not groups:
            try:
                groups.append(next(outer))
                log.append(('outer', type(groups[-1]).__name__, len(pulled)))
            except StopIteration:
                log.append(('outer', 'stop', len(pulled)))
        else:
            i = op % len(groups)
            try:
                log.append(('group', i, next(groups[i]), len(pulled)))
            except StopIteration:
                log.append(('group', i, 'stop', len(pulled)))
    return log

rng = random.Random(7)
double = lambda x: 2 * x
